import React, { useState } from 'react';

function MovieList({ movies, showtimes, currentUser, onSelectMovie, onGoToAuth }) {
  const [searchTerm, setSearchTerm] = useState('');
  const [genre, setGenre] = useState('Tất Cả');
  const [maxPrice, setMaxPrice] = useState(130000);
  const [sortBy, setSortBy] = useState('default');

  const genres = ['Tất Cả', 'Hoạt Hình', 'Hành Động', 'Viễn Tưởng', 'Kinh Dị'];

  const getMinPrice = (movieId) => {
    const movieShowtimes = showtimes.filter((item) => item.movie_id === movieId);
    if (!movieShowtimes.length) return 0;
    return Math.min(...movieShowtimes.map((item) => item.ticket_price));
  };

  const filteredMovies = movies
    .filter((movie) => {
      const titleMatch = movie.title.toLowerCase().includes(searchTerm.toLowerCase());
      const genreMatch = genre === 'Tất Cả' || movie.genre === genre;
      const priceMatch = getMinPrice(movie.id) <= maxPrice;
      return titleMatch && genreMatch && priceMatch;
    })
    .sort((a, b) => {
      if (sortBy === 'duration') return b.duration - a.duration;
      if (sortBy === 'price-asc') return getMinPrice(a.id) - getMinPrice(b.id);
      if (sortBy === 'price-desc') return getMinPrice(b.id) - getMinPrice(a.id);
      return 0;
    });

  return (
    <div>
      {/* Hàng tiêu đề song song với nút Đăng ký / Đăng nhập */}
      <div className="d-flex justify-content-between align-items-center mb-4 pb-2 border-bottom">
        <div>
          <h2 className="fw-bold text-uppercase m-0" style={{ color: '#7c3aed', letterSpacing: '0.5px' }}>
            🎬 Phim Đang Chiếu
          </h2>
          {currentUser && (
            <div className="text-secondary small mt-1">Xin chào, <strong>{currentUser.username}</strong></div>
          )}
        </div>
        
        <button 
          className="btn fw-bold px-4 py-2 rounded-pill shadow-sm text-white border-0"
          style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)' }}
          onClick={onGoToAuth}
        >
          🔑 Đăng Nhập / Đăng Ký
        </button>
      </div>

      {/* BỘ LỌC TÌM KIẾM */}
      <div className="card p-4 shadow-sm border-0 mb-5" style={{ backgroundColor: '#faf5ff', borderRadius: '16px' }}>
        <div className="row g-3 align-items-center">
          <div className="col-md-4">
            <label className="form-label fw-bold text-secondary small">Tìm kiếm tên phim</label>
            <input 
              type="text" 
              className="form-control border-0 shadow-sm" 
              style={{ borderRadius: '10px', padding: '10px 15px', borderBottom: '2px solid #7c3aed' }}
              placeholder="Nhập tên phim ..." 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
            />
          </div>
          <div className="col-md-4">
            <label className="form-label fw-bold text-secondary small">
              Giá vé tối đa: <span style={{ color: '#7c3aed' }} className="fw-black">{maxPrice.toLocaleString()}đ</span>
            </label>
            <input 
              type="range" 
              className="form-range" 
              min="80000" 
              max="130000" 
              step="5000" 
              value={maxPrice}
              style={{ accentColor: '#7c3aed' }}
              onChange={(e) => setMaxPrice(Number(e.target.value))} 
            />
          </div>
          <div className="col-md-4">
            <label className="form-label fw-bold text-secondary small">Sắp xếp theo</label>
            <select 
              className="form-select border-0 shadow-sm" 
              style={{ borderRadius: '10px', padding: '10px', borderBottom: '2px solid #7c3aed' }}
              value={sortBy} 
              onChange={(e) => setSortBy(e.target.value)}
            >
              <option value="default">Mặc định</option>
              <option value="duration">Thời lượng (Giảm dần)</option>
              <option value="price-asc">Giá vé (Thấp đến Cao)</option>
              <option value="price-desc">Giá vé (Cao đến Thấp)</option>
            </select>
          </div>
        </div>

        {/* NÚT THỂ LOẠI */}
        <div className="mt-4 border-top pt-3">
          <div className="d-flex flex-wrap gap-2">
            {genres.map((genreItem) => (
              <button
                key={genreItem}
                className={`btn btn-sm px-4 py-2 rounded-pill fw-bold`}
                style={{
                  backgroundColor: genre === genreItem ? '#7c3aed' : '#ffffff',
                  color: genre === genreItem ? '#ffffff' : '#64748b',
                  border: genre === genreItem ? 'none' : '1px solid #e2e8f0',
                  boxShadow: genre === genreItem ? '0 4px 12px rgba(124, 58, 237, 0.3)' : 'none'
                }}
                onClick={() => setGenre(genreItem)}
              >
                {genreItem}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* DANH SÁCH CARD PHIM */}
      <div className="row">
        {filteredMovies.map((movie) => {
          const minPrice = getMinPrice(movie.id);
          return (
            <div className="col-12 col-sm-6 col-md-4 mb-4" key={movie.id}>
              <div className="card h-100 border-0 shadow-sm overflow-hidden" style={{ borderRadius: '16px' }}>
                <div className="position-relative">
                  <img src={movie.image_url} className="card-img-top" alt={movie.title} style={{ height: '380px', objectFit: 'cover' }} />
                  <span className="position-absolute badge px-3 py-2 rounded-pill text-white fw-bold" style={{ top: '15px', left: '15px', backgroundColor: 'rgba(0, 0, 0, 0.6)' }}>
                    ⏱ {movie.duration} phút
                  </span>
                </div>
                
                <div className="card-body d-flex flex-column bg-white p-4">
                  <h5 className="card-title fw-bold text-dark text-truncate mb-2" style={{ fontSize: '1.2rem' }}>{movie.title}</h5>
                  <div className="mb-3">
                    <span className="badge px-3 py-2 rounded-3 fw-bold" style={{ backgroundColor: '#ede9fe', color: '#7c3aed' }}>
                      🏷 {movie.genre}
                    </span>
                  </div>
                  <p className="card-text text-muted flex-grow-1" style={{ fontSize: '0.85rem', lineHeight: '1.5' }}>
                    {movie.description}
                  </p>
                  <div className="d-flex gap-3 mb-3 small">
                    <div><span style={{ color: '#fbbf24' }}>⭐ {movie.rating}</span></div>
                    <div><span style={{ color: '#64748b' }}>👁 {movie.viewers.toLocaleString()} views</span></div>
                  </div>
                  <div className="border-top pt-3 mt-3 d-flex justify-content-between align-items-center">
                    <span className="text-secondary small fw-medium">Giá vé:</span>
                    <strong style={{ color: '#7c3aed' }} className="fs-4 fw-black">
                      {minPrice > 0 ? `${minPrice.toLocaleString()}đ` : 'Hết vé'}
                    </strong>
                  </div>
                  <button 
                    className="btn w-100 fw-bold mt-3 py-2 text-white border-0" 
                    style={{ background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)', borderRadius: '12px' }}
                    onClick={() => onSelectMovie(movie)}
                  >
                    🎟 Mua Vé Ngay
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default MovieList;
